    "pub_date": "2026-10-05 04:44:25",
    "author": "徐静",
    "description": "新华社纽约10月4日电（记者徐静）美国海岸警卫队东北区司令马特·莱克4日在新闻发布会上说，对3日失事飞机机上6人和黑匣子的搜寻工作仍在继续，鉴于飞机残骸涉及范围非常广，工作难度大。 莱克说，首要任务是找到6名机上人员，下一步是寻找飞机黑匣子。发现飞机残骸的地方距马萨诸塞州楠塔基特岛海岸约32公里，该区域水深24至28米。 据美国海岸警卫队发布的消息，搜救人员在27小时内搜寻了4000多平方公里的海域。3日晚间在海面发现了涉事飞机的残骸。…",
    "content": "新华社纽约10月4日电（记者徐静）美国海岸警卫队东北区司令马特·莱克4日在新闻发布会上说，对3日失事飞机机上6人和黑匣子的搜寻工作仍在继续，鉴于飞机残骸涉及范围非常广，工作难度大。 莱克说，首要任务是找到6名机上人员，下一步是寻找飞机黑匣子。发现飞机残骸的地方距马萨诸塞州楠塔基特岛海岸约32公里，该区域水深24至28米。 据美国海岸警卫队发布的消息，搜救人员在27小时内搜寻了4000多平方公里的海域。3日晚间在海面发现了涉事飞机的残骸。涉事飞机是湾流G100型喷气式飞机，用于医疗运输。 这架飞机原计划从百慕大韦德国…"
