    "content": "新华社耶路撒冷10月4日电（记者冯国芮 庞昕熠）据多家以色列媒体4日报道，迪拜航空公司客机驾驶舱冲突事件中的阿曼籍副驾驶哈马姆·哈马米接受审讯时称，他原本计划驾机撞向以色列特拉维夫本-古里安机场航站楼。 据以色列第12频道报道，哈马米选择在客机飞至约旦上空时袭击机长，原计划让飞机正常飞行至快要抵达本-古里安机场、以军机来不及实施拦截时，驾机撞向机场航站楼。受伤机长不惜一切代价打开驾驶舱门，挫败了哈马米的企图。 《耶路撒冷邮报》援引一名以色列消息人士称，哈马米在审讯中表示，他在被迪拜航空录用前就已策划袭击。他曾研究哪…"
