    "content": "新华社科威特城10月4日电（记者尹炣）亚丁消息：也门总统领导委员会主席拉沙德·阿里米4日在沙特阿拉伯首都利雅得宣布启动军事行动，以收复胡塞武装近期控制的地区。 阿里米当天在利雅得通过也门国家电视台发表电视讲话说，经过数周军事动员，也门政府正式启动大规模军事行动，以收复胡塞武装近期控制地区。他已命令武装部队、安全部门以及盟军各军事力量开始执行作战计划。 他表示，此次行动的任务“不仅是收复失地，更是恢复国家”。他还说，将对放下武器、停止战斗的胡塞武装人员予以赦免。 也门政府一名地方官员告诉新华社记者，胡塞武装4日在西南…"
