    "description": "新华社哈尔滨10月4日电（记者孙晓宇）眼下在我国粮食安全“压舱石”黑龙江，秋收正酣。在哈尔滨市依兰县达连河镇长兴村，大型联合收割机在玉米田中穿梭，金黄籽粒顺着卸粮管输入运粮车。种粮大户韩志民站在地头，望着一车车新粮，喜上眉梢：“今年是个丰收年！” 韩志民今年在依兰县种植1.3万亩玉米、1.1万亩大豆，秋收作业预计持续至11月中旬。为抢抓收获窗口期，他投入5台联合收割机，采取“人停机不停”作业模式。“2台玉米收割机单日就能收获1200亩，…",
    "content": "新华社哈尔滨10月4日电（记者孙晓宇）眼下在我国粮食安全“压舱石”黑龙江，秋收正酣。在哈尔滨市依兰县达连河镇长兴村，大型联合收割机在玉米田中穿梭，金黄籽粒顺着卸粮管输入运粮车。种粮大户韩志民站在地头，望着一车车新粮，喜上眉梢：“今年是个丰收年！” 韩志民今年在依兰县种植1.3万亩玉米、1.1万亩大豆，秋收作业预计持续至11月中旬。为抢抓收获窗口期，他投入5台联合收割机，采取“人停机不停”作业模式。“2台玉米收割机单日就能收获1200亩，就是要趁着好天气，抓紧把粮食收上来。”韩志民说。 说话间，他随手从田里掰下一穗玉…"
