    "description": "新华社日本名古屋10月4日电 综述：中国十二连冠 亚洲新星闪耀 赛事组织混乱 新华社记者王恒志、岳晨星 中国女排连克泰国、日本队卫冕，中国游泳队30金刷新历史最好成绩，中国男足时隔28年再获亚运奖牌，中国跳水队“十全十美”达成百金成就…… 在结束全部469个项目的比赛后，爱知·名古屋亚运会于4日落幕。中国体育代表团夺得169金89银83铜，实现亚运金牌榜十二连冠的同时，金牌总数创境外参赛新高。 10月4日，中国代表团在闭幕式上入场。新华…",
    "content": "新华社日本名古屋10月4日电 综述：中国十二连冠 亚洲新星闪耀 赛事组织混乱 新华社记者王恒志、岳晨星 中国女排连克泰国、日本队卫冕，中国游泳队30金刷新历史最好成绩，中国男足时隔28年再获亚运奖牌，中国跳水队“十全十美”达成百金成就…… 在结束全部469个项目的比赛后，爱知·名古屋亚运会于4日落幕。中国体育代表团夺得169金89银83铜，实现亚运金牌榜十二连冠的同时，金牌总数创境外参赛新高。 10月4日，中国代表团在闭幕式上入场。新华社记者 伍志尊 摄 从金牌榜和奖牌榜看，亚洲体坛整体格局变化不大。一些新星的崛起…"
