    "description": "新华社石家庄10月4日电（记者董笑坤、冯维健）国庆假期，位于河北省迁安市的白羊峪长城旅游区迎来客流高峰，慕名前来的游客络绎不绝。观景平台上，游客们伫立远眺，用相机定格长城与秋色交融的画面。 “这里的长城原始风貌很好，能感受到当年修筑长城所耗费的人力、物力，让孩子在游玩中感受历史。”来自北京的游客张晓栋说。 迁安市境内长城多为明代修筑，东起徐流口，西至红峪口，总长45.3公里。与人们熟悉的砖石长城不同，这里的部分城墙由当地大理石砌筑而成，…",
    "content": "新华社石家庄10月4日电（记者董笑坤、冯维健）国庆假期，位于河北省迁安市的白羊峪长城旅游区迎来客流高峰，慕名前来的游客络绎不绝。观景平台上，游客们伫立远眺，用相机定格长城与秋色交融的画面。 “这里的长城原始风貌很好，能感受到当年修筑长城所耗费的人力、物力，让孩子在游玩中感受历史。”来自北京的游客张晓栋说。 迁安市境内长城多为明代修筑，东起徐流口，西至红峪口，总长45.3公里。与人们熟悉的砖石长城不同，这里的部分城墙由当地大理石砌筑而成，山势、石色与城墙交织在一起，形成独特的景观。 图为迁安市境内的白羊峪长城。新华社…"
