    "author": "邹明仲",
    "description": "十一长假，天刚微亮，辽宁盘锦市胡家镇红星村的蟹田早已一派繁忙。养殖户们手持照明设备，穿梭在养殖塘间起网收蟹，地笼拉起的瞬间，肥硕鲜活的河蟹竞相跃动。 养殖户张怀斌一边分拣装箱，一边笑着说：“十月正是河蟹品质好、行情稳的时候，今年螃蟹个头大、品相优，市场销路广、收购价格稳定，收成和收入都有保障。”养殖塘的暂养池内，增氧设备持续运转，稳稳锁住河蟹鲜活品质，为批量外销、上市销售做好充足准备。 国网辽宁电力工作人员到稻蟹共生基地排查安全用电隐患…",
