    "content": "新华社北京10月4日电（记者谢希瑶）记者4日从商务部获悉，国庆假期过半，全国消费市场平稳有序，生活必需品货足价稳。 商务部商务大数据显示，国庆假期前三天（10月1至3日），商务部重点监测的78个步行街（商圈）客流量、营业额同比分别增长3.4%、5.3%。消费品以旧换新带动销售额196.3亿元，惠及348.3万人次。其中，汽车以旧换新4.6万辆，带动新车销售额74.5亿元；家电以旧换新151.1万台，带动销售额65.0亿元；数码和智能产品购新170.9万件，带动销售额49.0亿元。 各地生活必需品市场供应充足，价格总…"
