    "content": "新华社巴西利亚10月4日电（记者吴昊 陈昊佺）巴西2026年总统选举首轮投票于巴西利亚时间4日8时（北京时间19时）开始，首轮结果预计在当天投票结束后的数小时内揭晓。 此前巴西民调数据显示，巴西现任总统、劳工党候选人卢拉和前总统雅伊尔·博索纳罗之子、自由党候选人弗拉维奥·博索纳罗的支持率位居前两位，其他候选人的支持率与二人有较大差距。 据巴西高等选举法院公布的日程，若首轮投票中无候选人获得超过半数的有效选票，得票最多的两名候选人将于10月25日进入第二轮角逐。 10月4日，巴西现任总统、劳工党候选人卢拉在圣保罗州圣…"
