    "title": "亚运会丨专访李昊：水瓶扔了无所谓，反正他们也踢不进",
    "link": "http://www.news.cn/20261004/36a686b6b2c1401db6373c86e401c9d1/c.html",
    "pub_date": "2026-10-04 19:39:20",
