    "description": "新华社日本名古屋10月4日电 专访李昊：水瓶扔了无所谓，反正他们也踢不进 新华社记者肖世尧、王海洲、殷家捷 在3日进行的爱知·名古屋亚运会男足项目铜牌赛中，中国队与乌兹别克斯坦队常规时间2:2战平。点球大战中，门将李昊两度扑出点球，帮助中国队时隔28年再度获得亚运会男足铜牌。 在赛后接受新华社记者专访时，李昊露出他标志性的笑容，聊起点球大战的细节、球队的成长，也聊起主教练安东尼奥对自己的影响。谈到下一个目标，他说回国后要给妈妈补过一个生…",
