    "content": "新华社北京10月4日电 题：她来戴上那冠 新华社记者卢羽晨、季嘉东、高萌 在名古屋市综合体育馆，当海浪声响起，中国艺术体操队宛如一粒种子在礁石上萌发，顶着呼啸的海风，拼命向上生长。 10月3日，中国队在3圈2棒比赛中。图为中国队的开场造型。新华社记者 伍志尊 摄 这一幕，也恰如艺术体操项目的发展。虽然早在1896年首届现代奥运会就开始有竞技体操项目，但直至1984年，艺术体操才正式登上奥运舞台。 过往亚运会上，艺术体操除了个人全能之外，仅有个人团体。以上届亚运会为例，艺术体操的个人团体与竞技体操的团体项目类似，每队…"
