    "description": "重庆石柱县华溪村，地处群山深处。 村民谭登周在外出务工时受了重伤，卧床4个多月，靠医保等兜底政策渡过难关。 乘飞机、转火车、换汽车，2019年4月15日，习近平总书记千里迢迢、辗转奔波，来到老谭家。见到总书记，老谭一下子就哽咽了：“要不是党的政策好，我坟上的草都这么高啦！” 习近平总书记紧紧握着老谭的手：“党的政策对老百姓好，才是真正的好。” 一枝一叶，民生冷暖，在习近平总书记的心中有着沉甸甸的分量。从打赢脱贫攻坚战、全面建成小康社会，…",
    "content": "重庆石柱县华溪村，地处群山深处。 村民谭登周在外出务工时受了重伤，卧床4个多月，靠医保等兜底政策渡过难关。 乘飞机、转火车、换汽车，2019年4月15日，习近平总书记千里迢迢、辗转奔波，来到老谭家。见到总书记，老谭一下子就哽咽了：“要不是党的政策好，我坟上的草都这么高啦！” 习近平总书记紧紧握着老谭的手：“党的政策对老百姓好，才是真正的好。” 一枝一叶，民生冷暖，在习近平总书记的心中有着沉甸甸的分量。从打赢脱贫攻坚战、全面建成小康社会，到推进乡村全面振兴、向着共同富裕目标迈进，中华大地上的历史性变革，映照在山乡人家…"
