    "description": "（本文首发于南方人物周刊） 南方人物周刊记者 张宇欣 责任编辑：李屾淼 读作家郑执的新小说《朱砂掌》时，一个支线人物引起了我职业相关的兴趣。小说主角之一叫王润南，三十出头，在当自由写作者，有个分居的丈夫，丈夫和她本来在共同操作一篇报道，最重要的采访对象是这本小说的另一个主角——年过六十的女人朱玉环，犯了命案，被关在监狱。朱玉环少时习得铁砂掌功夫，因手掌变色，铁砂掌转而叫朱砂掌。 王润南与朱玉环有点渊源，她们都曾生活在沈阳大西菜行附近（郑…",
    "content": "（本文首发于南方人物周刊） 南方人物周刊记者 张宇欣 责任编辑：李屾淼 读作家郑执的新小说《朱砂掌》时，一个支线人物引起了我职业相关的兴趣。小说主角之一叫王润南，三十出头，在当自由写作者，有个分居的丈夫，丈夫和她本来在共同操作一篇报道，最重要的采访对象是这本小说的另一个主角——年过六十的女人朱玉环，犯了命案，被关在监狱。朱玉环少时习得铁砂掌功夫，因手掌变色，铁砂掌转而叫朱砂掌。 王润南与朱玉环有点渊源，她们都曾生活在沈阳大西菜行附近（ 郑执本人的生活故地以及他一些小说角色的故事发生地 ），也因着这点渊源，朱玉环拒绝…"
