    "link": "https://36kr.com/newsflashes/4011300895756420?f=rss",
    "pub_date": "2026-10-04 17:30:27",
    "author": "",
    "description": "近日，国际液冷企业维谛技术宣布收购欧洲KES公司。公开资料显示，KES公司为高密度液冷数据中心及其他应用提供流体管理、调试和负载测试服务。 维谛技术是全球较早通过并购来布局液冷产业的国际巨头。在过去4年中，维谛技术已收购了10家拥有不同业务特点的公司，大幅提升了公司技术能力。 业内人士表示，随着全球AIDC推进，维谛技术已逐步走出简单产品竞争，正在向综合运维和服务的方向发展，这一改变将极大改善公司综合服务能力和潜在盈利能力。相比较而言，…",
    "content": "近日，国际液冷企业维谛技术宣布收购欧洲KES公司。公开资料显示，KES公司为高密度液冷数据中心及其他应用提供流体管理、调试和负载测试服务。 维谛技术是全球较早通过并购来布局液冷产业的国际巨头。在过去4年中，维谛技术已收购了10家拥有不同业务特点的公司，大幅提升了公司技术能力。 业内人士表示，随着全球AIDC推进，维谛技术已逐步走出简单产品竞争，正在向综合运维和服务的方向发展，这一改变将极大改善公司综合服务能力和潜在盈利能力。相比较而言，目前国内液冷领域的收购仍集中在硬件领域，侧重快速进入国际液冷以及国内核心产业链。…"
