    "content": "新华社伦敦10月4日电 英国海上贸易行动办公室4日发布通报说，一艘油轮在霍尔木兹海峡遭袭。 通报说，该油轮被“不明发射物”击中，机舱受损，但船上人员安全，目前暂未收到关于环境影响的报告。 通报未提及事件发生的具体时间。相关调查正在进行。"
