    "description": "新华社基辅10月4日电（记者李东旭）乌克兰当地时间4日10时19分至30分左右，新华社记者在乌首都基辅听到乌军防空火力实施密集作业和强烈爆炸声。 10时20分，记者看到横跨第聂伯河的北桥附近升起浓烟，疑似一架无人机发生爆炸。 基辅市市长克利奇科在社交媒体发文称，北桥桥面受损。国家紧急情况局工作人员正在赶往现场。",
