    "content": "新华社萨拉热窝10月4日电（记者解园 宋佳）波黑4日举行大选，选举波黑主席团3名成员和波黑议会代表院42名议员。 波黑由波黑联邦和塞族共和国两个实体组成。本次大选还将选举波黑联邦议会代表院议员、波黑联邦各州议会议员，以及塞族共和国总统和副总统、塞族共和国国民议会议员。 波黑中央选举委员会表示，初步结果预计于4日20时公布。选举委员会网站信息显示，此次大选登记选民超过340万人，波黑境内共设5569个投票站，另在13个国家的20个外交和领事机构设立投票点。 此次大选中，波黑首次采用生物识别技术认证选民身份，并使用选票…"
