    "pub_date": "2026-10-04 16:26:54",
    "author": "文静,郎兵兵",
    "description": "新华社兰州10月4日电（记者文静、郎兵兵）秋收时节，黄土高原上的甘肃省天水市麦积区南山花牛苹果基地，果农挎着果筐在树行间采摘。几步之外，一台双臂机器人也在“干活”：高精度视觉识别系统锁定枝头的成熟苹果，机械臂末端轻轻一掰，苹果离枝，稳稳入筐。 “双臂协同一小时能摘果600到1000颗，大约比人工采摘快一倍。”北京市农林科学院助理研究员李亚军说，这款针对丘陵山地果园开发的机器人，突破了自然环境下熟果视觉识别、多臂协同作业等关键技术，可实现…",
    "content": "新华社兰州10月4日电（记者文静、郎兵兵）秋收时节，黄土高原上的甘肃省天水市麦积区南山花牛苹果基地，果农挎着果筐在树行间采摘。几步之外，一台双臂机器人也在“干活”：高精度视觉识别系统锁定枝头的成熟苹果，机械臂末端轻轻一掰，苹果离枝，稳稳入筐。 “双臂协同一小时能摘果600到1000颗，大约比人工采摘快一倍。”北京市农林科学院助理研究员李亚军说，这款针对丘陵山地果园开发的机器人，突破了自然环境下熟果视觉识别、多臂协同作业等关键技术，可实现自主采收、人机协同和遥控操作等多种模式。 在天水市麦积区南山花牛苹果基地，技术人…"
