    "description": "中新社天津10月4日电 (记者 周亚强)记者4日从总部位于天津的海洋石油工程股份有限公司(简称“海油工程”)获悉，中国首个海上注碳增气技术示范应用项目——东方1-1气田新建中心平台主体建造完工，全面进入调试阶段。项目投产后，每年可在海底地层封存二氧化碳超100万吨。",
    "content": "中新社天津10月4日电 (记者 周亚强)记者4日从总部位于天津的海洋石油工程股份有限公司(简称“海油工程”)获悉，中国首个海上注碳增气技术示范应用项目——东方1-1气田新建中心平台主体建造完工，全面进入调试阶段。项目投产后，每年可在海底地层封存二氧化碳超100万吨。"
