    "author": "魏冠宇",
    "description": "国庆假期，在中国人民革命军事博物馆展厅内，游客络绎不绝。经过一处模拟实景的“廊桥”，许多人第一眼就注意到桥柱上的一道刻痕。 这是正在举行的“伟大的远征——纪念中国工农红军长征胜利90周年主题展览”。“廊桥”的原物，坐落在福建长汀南山镇中复村。桥柱上的刻痕离地高约1.5米，是红军在当地征兵的身高标准。 10月3日，少年观众在“伟大的远征——纪念中国工农红军长征胜利90周年主题展览”聆听“生命等高线”的故事。新华社记者魏冠宇 摄 一对兄妹从…",
    "content": "国庆假期，在中国人民革命军事博物馆展厅内，游客络绎不绝。经过一处模拟实景的“廊桥”，许多人第一眼就注意到桥柱上的一道刻痕。 这是正在举行的“伟大的远征——纪念中国工农红军长征胜利90周年主题展览”。“廊桥”的原物，坐落在福建长汀南山镇中复村。桥柱上的刻痕离地高约1.5米，是红军在当地征兵的身高标准。 10月3日，少年观众在“伟大的远征——纪念中国工农红军长征胜利90周年主题展览”聆听“生命等高线”的故事。新华社记者魏冠宇 摄 一对兄妹从河北邯郸来到展厅，在柱前比高。 “过几年，你们就能长这么高了！”父亲顾雪辉笑着说…"
