    "description": "新华社香港10月4日电 香港特区政府财政司司长陈茂波4日发表网志表示，香港旅游业与金融市场持续活跃，国际联系与合作正不断深化，香港作为“超级联系人”和“超级增值人”的角色日益凸显。 陈茂波说，国庆黄金周前三天，已有超过73.2万人次内地旅客访港，按年增加约8.4%，入境处预计整个黄金周将有约129万人次内地旅客访港，日均人次按年上升超过5%。香港金融市场持续活跃，今年前9个月港股平均每日成交额达2729亿港元，同比增长6.4%；新股市场…",
    "content": "新华社香港10月4日电 香港特区政府财政司司长陈茂波4日发表网志表示，香港旅游业与金融市场持续活跃，国际联系与合作正不断深化，香港作为“超级联系人”和“超级增值人”的角色日益凸显。 陈茂波说，国庆黄金周前三天，已有超过73.2万人次内地旅客访港，按年增加约8.4%，入境处预计整个黄金周将有约129万人次内地旅客访港，日均人次按年上升超过5%。香港金融市场持续活跃，今年前9个月港股平均每日成交额达2729亿港元，同比增长6.4%；新股市场表现突出，共有116家企业在港上市，集资额逾3880亿港元，同比上升超过一倍。 …"
