    "author": "王宏彬",
    "description": "新华社北京10月4日电 最近从美国开放人工智能研究中心（OpenAI）离职的一名员工3日爆料前东家风险意识不足，并呼吁人工智能(AI)产业效仿航空或核能产业，采取多重安全防护措施。 这名员工名为戴维·鲁滨逊，自称曾在OpenAI工作3年多，是该公司任职最久的员工之一。他3日在美国《大西洋》月刊发表一篇题为《我辞去OpenAI的工作，因为企业文化已经烂掉了》的署名文章。 9月23日，在位于纽约的联合国总部，美国开放人工智能研究中心（Ope…",
    "content": "新华社北京10月4日电 最近从美国开放人工智能研究中心（OpenAI）离职的一名员工3日爆料前东家风险意识不足，并呼吁人工智能(AI)产业效仿航空或核能产业，采取多重安全防护措施。 这名员工名为戴维·鲁滨逊，自称曾在OpenAI工作3年多，是该公司任职最久的员工之一。他3日在美国《大西洋》月刊发表一篇题为《我辞去OpenAI的工作，因为企业文化已经烂掉了》的署名文章。 9月23日，在位于纽约的联合国总部，美国开放人工智能研究中心（OpenAI）首席执行官萨姆·奥尔特曼在“人工智能与国际安全”高级别会议现场发言。新华…"
