    "author": "杨舒怡",
    "description": "新华社北京10月4日电 美国田纳西州州长比尔·李3日说，该州监狱系统负责人弗兰克·斯特拉达已宣布辞职。这是该州一名女犯人被执行注射死刑失败后，监狱系统进行的一次重要人事调整。 启动调查 李说，田纳西州管教局局长斯特拉达将于本月离职，前联邦检察官埃德·斯坦顿将牵头调查这起令人震惊的行刑事故。 据美联社报道，田纳西州9月30日对50岁的女犯人克里斯塔·派克执行死刑，由于静脉输液管路出现故障，虽然犯人被注射了两剂致命药物，但并没有当场死亡。其…",
    "content": "新华社北京10月4日电 美国田纳西州州长比尔·李3日说，该州监狱系统负责人弗兰克·斯特拉达已宣布辞职。这是该州一名女犯人被执行注射死刑失败后，监狱系统进行的一次重要人事调整。 启动调查 李说，田纳西州管教局局长斯特拉达将于本月离职，前联邦检察官埃德·斯坦顿将牵头调查这起令人震惊的行刑事故。 据美联社报道，田纳西州9月30日对50岁的女犯人克里斯塔·派克执行死刑，由于静脉输液管路出现故障，虽然犯人被注射了两剂致命药物，但并没有当场死亡。其律师团队10月2日说，派克陷入昏迷，送医后依靠呼吸机维持生命。有关她的最新状况，…"
