    "author": "",
    "description": "杭甬高速复线宁波三期项目是国家高速公路杭甬高速复线的重要组成部分，也是世界第一大港——宁波舟山港的重要疏港公路，项目主线预计将于今年年底贯通。这个国庆假期，全线2700余名建设者坚守岗位，扎实推进各项关键节点施工，全力冲刺2027年年底建成目标。（央视新闻）",
