    "content": "新华社台北/济南10月4日电 题：台湾学者林安梧：扎根乡土与经典 践行“活的智慧” 新华社记者黄扬、马欣然、邵琨 讲坛、乡野、经典——对年届古稀的林安梧而言，三个词可以串联起数十年求索行迹。 身着唐装，头戴礼帽，语调从容舒缓……数十余载，林安梧往来于海峡两岸的书院与市井，将经典义理娓娓道来，用“仁”“礼”智慧沁润当下生活。 “真正的文化，不仅是故纸堆，更是活在日常生活里的智慧。”林安梧对记者说，优秀传统文化不应束之高阁，要把中华文化生生不息的精气神，浸润到每个中国人的日常生活中。 9月25日，林安梧在位于台北的住处…"
